const inp = $input.first().json;
const raw = (inp.choices && inp.choices[0] && inp.choices[0].message && inp.choices[0].message.content)
  ? inp.choices[0].message.content : '';
let parsed = {};
if (raw) {
  try { parsed = JSON.parse(raw); }
  catch (e) {
    try { parsed = JSON.parse(raw.replace(/```json/g,'').replace(/```/g,'')); }
    catch (err) {}
  }
}
const split = $('Split Candidates (Process One by One)1').first().json;
const email = parsed.recipient_email || split.email || '';
const name = split.candidate_name || '';
const position = split.position || '';
return [{ json: {
  subject: parsed.subject || 'Welcome to the Team',
  body: parsed.body || '',
  recipient_email: email,
  candidate_name: name,
  position: position
} }];

